"""Target Sum — count subsets, tracked as a dictionary of running sums.

Assigning +/- to every number is a subset-sum count in disguise; carrying a
map of sum -> ways handles the negative range without index shifting.

Time: O(n * sum)   Space: O(sum)
"""
from collections import defaultdict
from typing import List


class Solution:
    def findTargetSumWays(self, nums: List[int], target: int) -> int:
        ways = {0: 1}
        for value in nums:
            nxt = defaultdict(int)
            for total, count in ways.items():
                nxt[total + value] += count
                nxt[total - value] += count
            ways = nxt
        return ways.get(target, 0)
